	wire signed [SC+WY+1:0] p0 = Q0 * y0, p1 = Q1 * y1, p2 = Q2 * y2;
	wire signed [WY-1:0] y0n = R0 * x0 + ((p0 + HALF_SC) >>> SC);
	wire signed [WY-1:0] y1n = R1 * x0 + ((p1 + HALF_SC) >>> SC);
	wire signed [WY-1:0] y2n = R2 * x0 + ((p2 + HALF_SC) >>> SC);
