		always @(posedge clock) w_ph <= coef;
	end else begin : tbl
		(* romstyle = "M10K", ramstyle = "M10K" *) reg [4*30+2*36-1:0] rom_ph [0:63];
		initial $readmemb(MEM_PH, rom_ph);
		always @(posedge clock) if (wr_en) rom_ph[wr_addr] <= wr_data;
		always @(posedge clock) w_ph <= rom_ph[phase];
	end
	wire signed [29:0] T0v = w_ph[29:0],  T1v = w_ph[59:30], T2v = w_ph[89:60], T3v = w_ph[119:90];
	wire signed [35:0] R1v = w_ph[155:120], R2v = w_ph[191:156];
	reg signed [BITS_IN-1:0] x0 = 0;
	reg signed [BITS_IN+35:0] m0 = 0, m1 = 0, m2 = 0;
	reg signed [BC+BITS_IN+12:0] f0 = 0, f1 = 0, f2 = 0, f3 = 0, g1 = 0, g2 = 0, g3 = 0, fir = 0;
	reg signed [WS-1:0] s01 = 0, s2f = 0;
	wire signed [SC+WY+1:0] a0 = $signed({m0, 1'b1, {(SC-1){1'b0}}});
	wire signed [SC+WY+1:0] a1 = $signed({m1, 1'b1, {(SC-1){1'b0}}});
	wire signed [SC+WY+1:0] a2 = $signed({m2, 1'b1, {(SC-1){1'b0}}});
