		if (rst) begin
			x0 <= 0;
			m0 <= 0; m1 <= 0; m2 <= 0;
			f0 <= 0; f1 <= 0; f2 <= 0; f3 <= 0; g1 <= 0; g2 <= 0; g3 <= 0; fir <= 0;
			y0 <= 0; y1 <= 0; y2 <= 0;
			s01 <= 0; s2f <= 0; acc <= 0;
		end else begin
			x0 <= in;
			m0 <= R0 * x0; m1 <= R1v * x0; m2 <= R2v * x0;
			f0 <= T0v * x0; f1 <= T1v * x0; f2 <= T2v * x0; f3 <= T3v * x0;
			g3 <= f3; g2 <= g3 + f2; g1 <= g2 + f1;
			fir <= g1 + f0;
			y0 <= n0 >>> SC; y1 <= n1 >>> SC; y2 <= n2 >>> SC;
			s01 <= y0 + y1;
			s2f <= y2 + (fir <<< (F - BC)) + HALF_F;
			acc <= (s01 + s2f) >>> F;
		end
end
endgenerate

assign out = acc;

endmodule
